def parse_tsp_strings(tsp_strings):
    """
    Parse multiple TSP input strings to extract coordinates and solutions.
    
    Args:
        tsp_strings (list): List of strings in format "coord1 coord2 ... coordN output sol1 sol2 ... solN start_node"
        
    Returns:
        list: List of tuples (coordinates, solution)
    """
    results = []
    
    for tsp_string in tsp_strings:
        parts = tsp_string.strip().split()
        
        # Find the 'output' keyword
        try:
            output_idx = parts.index('output')
        except ValueError:
            raise ValueError("Could not find 'output' keyword in the string")
        
        # Extract coordinates (pairs of x,y coordinates)
        coord_strs = parts[:output_idx]
        if len(coord_strs) % 2 != 0:
            raise ValueError(f"Number of coordinate values ({len(coord_strs)}) must be even")
        
        coordinates = []
        for i in range(0, len(coord_strs), 2):
            x = float(coord_strs[i])
            y = float(coord_strs[i + 1])
            coordinates.append([x, y])
        
        # Extract solution (nodes in order)
        solution_strs = parts[output_idx + 1:]
        solution = [int(s) for s in solution_strs]
        
        results.append((np.array(coordinates), solution))
    
    return results


def parse_tsp_string(tsp_string):
    """
    Parse a single TSP input string to extract coordinates and solution.
    
    Args:
        tsp_string (str): String in format "coord1 coord2 ... coordN output sol1 sol2 ... solN start_node"
        
    Returns:
        tuple: (coordinates, solution)
    """
    return parse_tsp_strings([tsp_string])[0]


def create_tsp_batch(coordinates_list, batch_size=1, neighbors=20, knn_strat='percentage'):
    """
    Create a batch of TSP instances from multiple coordinates using TSPDataset.
    
    Args:
        coordinates_list (list): List of coordinate arrays, each of shape (num_nodes, 2)
        batch_size (int): Batch size to create
        neighbors (int): Number of neighbors for k-NN graph computation
        knn_strat (str): Strategy for computing k-NN graphs ('percentage'/'standard')
        
    Returns:
        dict: Batch dictionary with 'nodes' and 'graph' keys
    """
    from problems.tsp.problem_tsp import TSPDataset
    
    # Create a temporary file with the TSP data
    import tempfile
    import os
    
    # Create temporary file
    with tempfile.NamedTemporaryFile(mode='w', suffix='.txt', delete=False) as f:
        for coordinates in coordinates_list:
            # Format the coordinates and solution as a TSP string
            coord_str = " ".join([f"{coord[0]} {coord[1]}" for coord in coordinates])
            # Create a dummy solution (this won't be used for embeddings, but needed for dataset format)
            solution = list(range(1, len(coordinates) + 1)) + [1]  # 1-indexed tour
            solution_str = " ".join(map(str, solution))
            tsp_string = f"{coord_str} output {solution_str}"
            f.write(tsp_string + '\n')
        temp_filename = f.name
    
    try:
        # Create dataset with the same parameters as in eval.py
        dataset = TSPDataset(
            filename=temp_filename,
            batch_size=batch_size,
            num_samples=len(coordinates_list),
            neighbors=neighbors,
            knn_strat=knn_strat,
            supervised=False
        )
        
        # Collect all items
        all_nodes = []
        all_graphs = []
        
        for i in range(len(dataset)):
            item = dataset[i]
            all_nodes.append(item['nodes'])
            all_graphs.append(item['graph'])
        
        # Stack into batches
        nodes = torch.stack(all_nodes, dim=0)
        graphs = torch.stack(all_graphs, dim=0)
        
        return {
            'nodes': nodes,
            'graph': graphs
        }
    
    finally:
        # Clean up temporary file
        os.unlink(temp_filename)


def get_model_embeddings(tsp_strings, model_path, save_dir="embeddings", batch_size=1, checkpoint_encoder=False):
    """
    Process multiple TSP input strings, run them through a model, and save the embeddings.
    
    Args:
        tsp_strings (list): List of TSP input strings with coordinates and solutions
        model_path (str): Path to the model checkpoint
        save_dir (str): Directory to save embeddings
        batch_size (int): Batch size for processing
        checkpoint_encoder (bool): Whether to use checkpointing for encoder
        
    Returns:
        str: Path to the saved embeddings file
    """
    # Parse the input strings
    parsed_data = parse_tsp_strings(tsp_strings)
    coordinates_list = [data[0] for data in parsed_data]
    solutions_list = [data[1] for data in parsed_data]
    
    num_samples = len(coordinates_list)
    num_nodes_list = [len(coords) for coords in coordinates_list]
    
    print(f"Parsed {num_samples} TSP instances")
    for i, (coords, sol) in enumerate(zip(coordinates_list, solutions_list)):
        print(f"  Sample {i+1}: {len(coords)} nodes, solution: {sol}")
    
    # Load the model
    print(f"Loading model from {model_path}")
    model, model_args = load_model(model_path)
    
    if not isinstance(model, AttentionModel):
        raise ValueError("Model must be an AttentionModel to extract embeddings")
    
    # Set device
    use_cuda = torch.cuda.is_available()
    device = torch.device("cuda:0" if use_cuda else "cpu")
    print(f"Using device: {device}")
    
    # Move model to device
    model.to(device)
    model.eval()
    
    # Create batch using the same parameters as the model was trained with
    neighbors = model_args.get('neighbors', 20)
    knn_strat = model_args.get('knn_strat', 'percentage')
    
    batch = create_tsp_batch(coordinates_list, batch_size, neighbors=neighbors, knn_strat=knn_strat)
    nodes = move_to(batch['nodes'], device)
    graph = move_to(batch['graph'], device)
    
    print(f"Processing batch with shape: nodes {nodes.shape}, graph {graph.shape}")
    print(f"Using checkpoint_encoder: {checkpoint_encoder}")
    
    # Get embeddings by running through the model
    with torch.no_grad():
        # Get encoder embeddings (lines 188-191 from attention_model.py)
        if checkpoint_encoder:
            embeddings = torch.utils.checkpoint.checkpoint(model.embedder, model._init_embed(nodes), graph)
        else:
            embeddings = model.embedder(model._init_embed(nodes), graph)
        
        if model.extra_logging:
            model.embeddings_batch = embeddings
    
    # Create output directory
    os.makedirs(save_dir, exist_ok=True)
    
    # Generate filename
    embedding_dim = model.embedding_dim
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    # Use range of node counts for filename
    min_nodes = min(num_nodes_list)
    max_nodes = max(num_nodes_list)
    node_range = f"{min_nodes}-{max_nodes}" if min_nodes != max_nodes else str(min_nodes)
    filename = f"{num_samples}samples_{node_range}nodes_edim{embedding_dim}_{timestamp}.pt"
    filepath = os.path.join(save_dir, filename)
    
    # Prepare data to save
    save_data = {
        'coordinates_list': coordinates_list,
        'solutions_list': solutions_list,
        'num_samples': num_samples,
        'num_nodes_list': num_nodes_list,
        'embedding_dim': embedding_dim,
        'model_args': model_args,
        'embeddings': embeddings.cpu(),
        'timestamp': timestamp
    }
    
    # Save embeddings
    torch.save(save_data, filepath)
    print(f"Saved embeddings to: {filepath}")
    
    return filepath


